t.script:
                class ModernBooksAPI {
                    constructor() {
                        this.currentPage = 1;
                        this.itemsPerPage = 12;
                        this.currentFilter = 'all';
                        this.books = [];
                        this.init();
                    }

                    init() {
                        this.bindEvents();
                        this.loadBooks();
                        this.updateStats();
                    }

                    bindEvents() {
                        // Recherche
                        document.getElementById('searchBtn').addEventListener('click', () => {
                            this.searchBooks();
                        });

                        document.getElementById('searchInput').addEventListener('keypress', (e) => {
                            if (e.key === 'Enter') {
                                this.searchBooks();
                            }
                        });

                        // Filtres
                        document.querySelectorAll('.filter-btn').forEach(btn => {
                            btn.addEventListener('click', (e) => {
                                this.currentFilter = e.target.dataset.filter;
                                this.updateFilterButtons();
                                this.filterBooks();
                            });
                        });
                    }

                    updateFilterButtons() {
                        document.querySelectorAll('.filter-btn').forEach(btn => {
                            btn.classList.remove('active');
                        });
                        document.querySelector(`[data-filter="${this.currentFilter}"]`).classList.add('active');
                    }

                    async loadBooks() {
                        this.showLoading(true);
                        try {
                            const response = await fetch('/api/books');
                            const data = await response.json();

                            if (data.success) {
                                this.books = data.data;
                                this.displayBooks();
                                this.updateStats();
                            } else {
                                this.showError('Erreur lors du chargement des livres');
                            }
                        } catch (error) {
                            this.showError('Erreur de connexion');
                        } finally {
                            this.showLoading(false);
                        }
                    }

                    async searchBooks() {
                        const searchTerm = document.getElementById('searchInput').value.trim();
                        if (!searchTerm) {
                            this.loadBooks();
                            return;
                        }

                        this.showLoading(true);
                        try {
                            const response = await fetch(`/api/books/search?q=${encodeURIComponent(searchTerm)}`);
                            const data = await response.json();

                            if (data.success) {
                                this.books = data.data;
                                this.displayBooks();
                                this.updateStats();
                            } else {
                                this.showError(data.error || 'Erreur lors de la recherche');
                            }
                        } catch (error) {
                            this.showError('Erreur de connexion');
                        } finally {
                            this.showLoading(false);
                        }
                    }

                    filterBooks() {
                        const filteredBooks = this.books.filter(book => {
                            if (this.currentFilter === 'all') return true;
                            return book.state === this.currentFilter;
                        });

                        this.displayBooks(filteredBooks);
                        this.updateStats(filteredBooks);
                    }

                    updateStats(booksToCount = null) {
                        const books = booksToCount || this.books;
                        const stats = {
                            total: books.length,
                            available: books.filter(b => b.state === 'available').length,
                            borrowed: books.filter(b => b.state === 'borrowed').length,
                            lost: books.filter(b => b.state === 'lost').length
                        };

                        document.getElementById('totalCount').textContent = stats.total;
                        document.getElementById('availableCount').textContent = stats.available;
                        document.getElementById('borrowedCount').textContent = stats.borrowed;
                        document.getElementById('lostCount').textContent = stats.lost;
                    }

                    displayBooks(booksToDisplay = null) {
                        const container = document.getElementById('booksContainer');
                        const books = booksToDisplay || this.books;

                        if (books.length === 0) {
                            container.innerHTML = '

Aucun livre trouvé';
                            return;
                        }

                        const startIndex = (this.currentPage - 1) * this.itemsPerPage;
                        const endIndex = startIndex + this.itemsPerPage;
                        const paginatedBooks = books.slice(startIndex, endIndex);

                        container.innerHTML = paginatedBooks.map(book => this.createBookCard(book)).join('');
                        this.updatePagination(books.length);
                    }

                    createBookCard(book) {
                        const stateClass = {
                            'available': 'success',
                            'borrowed': 'warning',
                            'lost': 'danger'
                        }[book.state] || 'secondary';

                        const authors = book.authors ? book.authors.map(author => author.name).join(', ') : 'Auteur inconnu';
                        const category = book.category ? book.category.name : 'Catégorie inconnue';
                        const publisher = book.publisher ? book.publisher.name : 'Éditeur inconnu';

                        return `







                                        ${book.state}




${book.name}

${authors}

${category}

${publisher}
                                        ${book.isbn ? `
ISBN: ${book.isbn}` : ''}



                        `;
                    }

                    updatePagination(totalItems) {
                        const totalPages = Math.ceil(totalItems / this.itemsPerPage);
                        const pagination = document.getElementById('pagination');

                        if (totalPages <= 1) {
                            pagination.innerHTML = '';
                            return;
                        }

                        let paginationHTML = '';

                        // Bouton précédent
                        paginationHTML += `


                                Précédent

                        `;

                        // Pages
                        for (let i = 1; i <= totalPages; i++) {
                            if (i === 1 || i === totalPages || (i >= this.currentPage - 2 && i <= this.currentPage + 2)) {
                                paginationHTML += `


                                        ${i}

                                `;
                            } else if (i === this.currentPage - 3 || i === this.currentPage + 3) {
                                paginationHTML += '
...';
                            }
                        }

                        // Bouton suivant
                        paginationHTML += `


                                Suivant

                        `;

                        pagination.innerHTML = paginationHTML;
                    }

                    changePage(page) {
                        this.currentPage = page;
                        this.displayBooks();
                    }

                    async showBookDetails(bookId) {
                        try {
                            const response = await fetch(`/api/books/${bookId}`);
                            const data = await response.json();

                            if (data.success) {
                                const book = data.data;
                                this.displayBookModal(book);
                            } else {
                                this.showError('Erreur lors du chargement des détails');
                            }
                        } catch (error) {
                            this.showError('Erreur de connexion');
                        }
                    }

                    displayBookModal(book) {
                        const modalTitle = document.getElementById('bookModalTitle');
                        const modalBody = document.getElementById('bookModalBody');

                        modalTitle.textContent = book.name;

                        const authors = book.authors ? book.authors.map(author => author.name).join(', ') : 'Auteur inconnu';
                        const category = book.category ? book.category.name : 'Catégorie inconnue';
                        const publisher = book.publisher ? book.publisher.name : 'Éditeur inconnu';

                        modalBody.innerHTML = `









Description

${book.description || 'Aucune description disponible'}


Informations


Auteurs: ${authors}

Catégorie: ${category}

Éditeur: ${publisher}
                                        ${book.isbn ? `
ISBN: ${book.isbn}` : ''}
                                        ${book.publication_date ? `
Date de publication: ${book.publication_date}` : ''}

État: ${book.state}
                                        ${book.loan_date ? `
Date d'emprunt: ${book.loan_date}` : ''}
                                        ${book.return_date ? `
Date de retour: ${book.return_date}` : ''}



                        `;

                        $('#bookModal').modal('show');
                    }

                    showLoading(show) {
                        const loading = document.getElementById('loading');
                        if (show) {
                            loading.classList.remove('d-none');
                        } else {
                            loading.classList.add('d-none');
                        }
                    }

                    showError(message) {
                        const container = document.getElementById('booksContainer');
                        container.innerHTML = `




                                    ${message}


                        `;
                    }
                }

                // Initialisation
                let modernBooksAPI;
                document.addEventListener('DOMContentLoaded', function() {
                    modernBooksAPI = new ModernBooksAPI();
                });
